package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() throws NumberFormatException {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_DoubleDash() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hex() throws NumberFormatException {
        // Tests the str.startsWith("0x") or str.startsWith("-0x") branch
        Number res = NumberUtils.createNumber("0x10");
        assertTrue(res instanceof Integer);
        assertEquals(16, res.intValue());

        Number resNeg = NumberUtils.createNumber("-0x10");
        assertTrue(resNeg instanceof Integer);
        assertEquals(-16, resNeg.intValue());
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        // Integer
        Number n1 = NumberUtils.createNumber("123");
        assertTrue(n1 instanceof Integer);
        assertEquals(123, n1.intValue());

        // Long
        Number n2 = NumberUtils.createNumber("1234567890123");
        assertTrue(n2 instanceof Long);
        assertEquals(1234567890123L, n2.longValue());

        // BigInteger (Too big for long)
        String bigStr = "123456789012345678901234567890";
        Number n3 = NumberUtils.createNumber(bigStr);
        assertTrue(n3 instanceof BigInteger);
        assertEquals(new BigInteger(bigStr), n3);
    }

    @Test
    public void testCreateNumber_FloatingPointTypes() throws NumberFormatException {
        // Float
        Number f = NumberUtils.createNumber("1.23f");
        assertTrue(f instanceof Float);
        assertEquals(1.23f, f.floatValue(), 0.001f);

        // Double
        Number d = NumberUtils.createNumber("1.23d");
        assertTrue(d instanceof Double);
        assertEquals(1.23, d.doubleValue(), 0.001);

        // BigDecimal (via fallback)
        Number bd = NumberUtils.createNumber("1.234567890123456789");
        // If it's too precise for double, it should be BigDecimal
        if (!(bd instanceof Double)) {
            assertTrue(bd instanceof BigDecimal);
        }
    }

    @Test
    public void testCreateNumber_ExplicitSuffixes() throws NumberFormatException {
        // Long suffix L
        Number l = NumberUtils.createNumber("123L");
        assertTrue(l instanceof Long);

        // BigInteger suffix L (too big for long)
        String bigL = "9223372036854775808L"; 
        Number bi = NumberUtils.createNumber(bigL);
        assertTrue(bi instanceof BigInteger);

        // Float suffix F
        Number fl = NumberUtils.createNumber("1.2F");
        assertTrue(fl instanceof Float);

        // Double suffix D
        Number dl = NumberUtils.createNumber("1.2D");
        assertTrue(dl instanceof Double);
    }

    @Test
    public void testCreateNumber_ScientificNotation() throws NumberFormatException {
        // No decimal, with exponent
        Number n1 = NumberUtils.createNumber("1e3");
        // Depending on implementation, might be Double or Float. 
        // The logic tries Float first.
        assertTrue(n1 instanceof Float || n1 instanceof Double);
        assertEquals(1000.0, n1.doubleValue(), 0.001);

        // With decimal and exponent
        Number n2 = NumberUtils.createNumber("1.23e2");
        assertEquals(123.0, n2.doubleValue(), 0.001);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExponentPosition() throws NumberFormatException {
        // expPos < decPos case
        NumberUtils.createNumber("1e.5");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        // Case where lastChar is not digit/dot and not a valid suffix
        NumberUtils.createNumber("123z");
    }

    @Test
    public void testCreateNumber_AllZerosLogic() throws NumberFormatException {
        // Tests the allZeros check for precision/infinite logic
        // "0.00000000000000000000000000000000000001" is not all zeros
        Number n1 = NumberUtils.createNumber("0.00000000000000000000000000000000000001");
        assertNotNull(n1);

        // "0.00000000000000000000000000000000000000" is all zeros
        Number n2 = NumberUtils.createNumber("0.00000000000000000000000000000000000000");
        assertNotNull(n2);
    }

    @Test
    public void testCreateNumber_ComplexScientificSuffix() throws NumberFormatException {
        // Testing the branch: if (!Character.isDigit(lastChar) && lastChar != '.')
        // specifically the exp = str.substring(expPos + 1, str.length() - 1);
        // Example: "1.2e3f" -> numeric="1.2e3", exp="3", lastChar='f'
        Number n = NumberUtils.createNumber("1.2e3f");
        assertTrue(n instanceof Float);
        assertEquals(1200.0f, n.floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_NegativeLong() throws NumberFormatException {
        Number n = NumberUtils.createNumber("-123L");
        assertTrue(n instanceof Long);
        assertEquals(-123L, n.longValue());
    }

    @Test
    public void testCreateNumber_FloatFallbackToDouble() throws NumberFormatException {
        // A number that is too large for Float but fits in Double
        // Or a number that causes Float to be infinite
        Number n = NumberUtils.createNumber("1e40f"); 
        // 1e40 is > Float.MAX_VALUE
        // The code says: if (!(f.isInfinite() || ...)) { return f; } 
        // Since it is infinite, it falls through to Double.
        assertTrue(n instanceof Double);
    }
}
